// The tests in this file check that GoForge can safely keep extending a project:
// one generated by an earlier release, one its developers have edited, and one
// that lost a marker comment.

// TestExtendProjectsFromEarlierReleases generates a project with each earlier
// release and extends it with the current version. What an old project lacks
// must never be papered over: the command either works and leaves a project
// that builds and passes its tests, or fails with outdated_project and changes
// nothing.
func TestExtendProjectsFromEarlierReleases(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping end-to-end upgrade test in short mode")
	}
	if _, err := exec.LookPath("go"); err != nil {
		t.Skip("go toolchain not found in PATH")
	}

	container := newContainer(t)
	newProject := func(t *testing.T, version string) string {
		t.Helper()
		old := installRelease(t, version)
		dir := t.TempDir()
		runBinary(t, dir, old, "generate", "-n", "shop", "-m", "github.com/acme/shop", "-o", dir, "--yes")
		project := filepath.Join(dir, "shop")
		runBinary(t, project, old, "add", "resource", "product", "--fields", "name:string,price:float")
		return project
	}
	category := func(project string) *domain.ResourceConfig {
		return &domain.ResourceConfig{ProjectDir: project, Name: "category", Fields: []domain.Field{{Name: "title", Type: domain.FieldString}}}
	}
	review := func(project string) *domain.ResourceConfig {
		return &domain.ResourceConfig{ProjectDir: project, Name: "review", Fields: []domain.Field{
			{Name: "product_id", Type: domain.FieldRef, Ref: "product"},
			{Name: "rating", Type: domain.FieldInt, Min: bound(1), Max: bound(5)},
		}}
	}

	t.Run("v0.1.0 projects are refused, unchanged", func(t *testing.T) {
		project := newProject(t, "v0.1.0")
		before := snapshot(t, project)
		_, err := container.ResourceGeneratorUsecase.Add(category(project))
		if code := domain.ErrorCode(err); code != domain.CodeOutdatedProject {
			t.Fatalf("add resource error code = %q, want %q: %v", code, domain.CodeOutdatedProject, err)
		}
		assertUnchanged(t, project, before)
	})

	t.Run("v0.2.0 projects take new resources and a database", func(t *testing.T) {
		project := newProject(t, "v0.2.0")
		addResource(t, container, category(project))
		if _, err := container.DatabaseGeneratorUsecase.Add(&domain.DatabaseConfig{ProjectDir: project, Engine: domain.DatabaseSQLite}); err != nil {
			t.Fatalf("adding a database to a v0.2.0 project: %v", err)
		}

		assertGofmtClean(t, project)
		runGo(t, project, "vet", "./...")
		runGo(t, project, "test", "-count=1", "./...")

		baseURL := buildAndStart(t, project, "DATABASE_URL="+filepath.Join(t.TempDir(), "shop.db"))
		for _, resource := range []struct{ path, body string }{
			{"/products", `{"name":"Gopher plush","price":19.5}`},
			{"/categories", `{"title":"Toys"}`},
		} {
			if status, _, body := request(t, http.MethodPost, baseURL+resource.path, resource.body); status != http.StatusCreated {
				t.Errorf("POST %s = %d %s, want 201", resource.path, status, body)
			}
		}
	})

	t.Run("v0.2.0 projects refuse references to their old resources, unchanged", func(t *testing.T) {
		project := newProject(t, "v0.2.0")
		before := snapshot(t, project)
		_, err := container.ResourceGeneratorUsecase.Add(review(project))
		if code := domain.ErrorCode(err); code != domain.CodeOutdatedProject {
			t.Fatalf("add resource error code = %q, want %q: %v", code, domain.CodeOutdatedProject, err)
		}
		assertUnchanged(t, project, before)
	})
}

// TestHandEditsSurvive edits generated code the way a developer would (a
// business rule, a handler, a custom route), then adds a resource and a
// database. Every edit must still be there, and still work.
func TestHandEditsSurvive(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping end-to-end hand edits test in short mode")
	}
	if _, err := exec.LookPath("go"); err != nil {
		t.Skip("go toolchain not found in PATH")
	}

	container := newContainer(t)
	project := generateProject(t, container)
	addResource(t, container, &domain.ResourceConfig{ProjectDir: project, Name: "product", Fields: []domain.Field{
		{Name: "name", Type: domain.FieldString},
		{Name: "price", Type: domain.FieldFloat},
	}})

	edits := map[string][2]string{
		// A business rule in the place GoForge made for it
		"products/rules.go": {"\tvar problems []string\n", "\tvar problems []string\n" +
			"\tif in.Name == \"forbidden\" {\n\t\tproblems = append(problems, \"name is not allowed\")\n\t}\n"},
		// A change to a generated handler
		"products/handler.go": {"package products\n", "package products\n\n// Hand-edited: this comment must survive.\n"},
		// A custom route next to the generated ones
		"server/routes.go": {"\tmux.HandleFunc(\"GET /readyz\", handlers.Ready(deps.Ready))\n",
			"\tmux.HandleFunc(\"GET /readyz\", handlers.Ready(deps.Ready))\n" +
				"\tmux.HandleFunc(\"GET /hello\", func(w http.ResponseWriter, _ *http.Request) { _, _ = w.Write([]byte(\"hello\")) })\n"},
	}
	for file, edit := range edits {
		editFile(t, filepath.Join(project, file), edit[0], edit[1])
	}

	addResource(t, container, &domain.ResourceConfig{ProjectDir: project, Name: "category", Fields: []domain.Field{{Name: "title", Type: domain.FieldString}}})
	if _, err := container.DatabaseGeneratorUsecase.Add(&domain.DatabaseConfig{ProjectDir: project, Engine: domain.DatabaseSQLite}); err != nil {
		t.Fatalf("adding a database: %v", err)
	}

	for file, edit := range edits {
		content, err := os.ReadFile(filepath.Join(project, file))
		if err != nil {
			t.Fatal(err)
		}
		if !strings.Contains(string(content), edit[1]) {
			t.Errorf("the edit to %s was lost:\n%s", file, content)
		}
	}

	assertGofmtClean(t, project)
	runGo(t, project, "vet", "./...")
	runGo(t, project, "test", "-count=1", "./...")

	baseURL := buildAndStart(t, project, "DATABASE_URL="+filepath.Join(t.TempDir(), "shop.db"))
	if status, _, body := request(t, http.MethodGet, baseURL+"/hello", ""); status != http.StatusOK || string(body) != "hello" {
		t.Errorf("GET /hello = %d %s, want the custom route", status, body)
	}
	if status, _, body := request(t, http.MethodPost, baseURL+"/products", `{"name":"forbidden","price":1}`); status != http.StatusUnprocessableEntity {
		t.Errorf("POST a product breaking the custom rule = %d %s, want 422", status, body)
	}
	if status, _, body := request(t, http.MethodPost, baseURL+"/categories", `{"title":"Toys"}`); status != http.StatusCreated {
		t.Errorf("POST /categories = %d %s, want 201", status, body)
	}
}

// TestMissingMarkerChangesNothing removes each marker comment of a generated
// project in turn and runs every command that edits a project. Each command
// must either work or fail with marker_missing and leave every file as it was.
func TestMissingMarkerChangesNothing(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping end-to-end marker test in short mode")
	}
	if _, err := exec.LookPath("go"); err != nil {
		t.Skip("go toolchain not found in PATH")
	}

	container := newContainer(t)
	original := generateProject(t, container)
	addResource(t, container, &domain.ResourceConfig{ProjectDir: original, Name: "product", Fields: []domain.Field{{Name: "name", Type: domain.FieldString}}})

	markers := findMarkers(t, original)
	if len(markers) < 5 {
		t.Fatalf("found %d markers, want at least 5: %v", len(markers), markers)
	}

	commands := []struct {
		name string
		run  func(project string) error
	}{
		{"add resource", func(project string) error {
			_, err := container.ResourceGeneratorUsecase.Add(&domain.ResourceConfig{ProjectDir: project, Name: "category", Fields: []domain.Field{{Name: "title", Type: domain.FieldString}}})
			return err
		}},
		{"add db", func(project string) error {
			_, err := container.DatabaseGeneratorUsecase.Add(&domain.DatabaseConfig{ProjectDir: project, Engine: domain.DatabaseSQLite})
			return err
		}},
	}

	for _, m := range markers {
		for _, c := range commands {
			t.Run(m.name+"/"+c.name, func(t *testing.T) {
				project := filepath.Join(t.TempDir(), "shop")
				copyDir(t, original, project)
				editFile(t, filepath.Join(project, m.file), m.line, "")
				before := snapshot(t, project)

				err := c.run(project)
				if err == nil {
					// The command didn't need this marker, so its result must still build
					runGo(t, project, "build", "./...")
					return
				}
				if code := domain.ErrorCode(err); code != domain.CodeMarkerMissing {
					t.Errorf("error code = %s, want %s: %v", code, domain.CodeMarkerMissing, err)
				}
				assertUnchanged(t, project, before)
			})
		}
	}
}

func newContainer(t *testing.T) *di.Container {
	t.Helper()
	templates, err := fs.Sub(TemplatesFS, "templates")
	if err != nil {
		t.Fatalf("Failed to open embedded templates: %v", err)
	}
	container, err := di.BuildContainer(templates, di.Options{})
	if err != nil {
		t.Fatalf("Failed to build container: %v", err)
	}
	return container
}

// generateProject generates a project with the current version and returns its path.
func generateProject(t *testing.T, container *di.Container) string {
	t.Helper()
	config := &domain.ServerConfig{AppName: "shop", ModulePath: "github.com/acme/shop", Port: 8080, OutputDir: t.TempDir(), IncludeLogger: true}
	if err := container.ServerGeneratorUsecase.Generate(config); err != nil {
		t.Fatalf("Failed to generate server: %v", err)
	}
	return config.GetProjectPath()
}

func addResource(t *testing.T, container *di.Container, r *domain.ResourceConfig) {
	t.Helper()
	if _, err := container.ResourceGeneratorUsecase.Add(r); err != nil {
		t.Fatalf("Failed to add resource %s: %v", r.Name, err)
	}
}

// installRelease installs a released version of GoForge and returns the path
// of its binary.
func installRelease(t *testing.T, version string) string {
	t.Helper()
	bin := t.TempDir()
	cmd := exec.Command("go", "install", "github.com/Frank5ive/goforge@"+version)
	cmd.Env = append(os.Environ(), "GOBIN="+bin, "GOFLAGS=")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("go install goforge@%s: %v\n%s", version, err, out)
	}
	binary := filepath.Join(bin, "goforge")
	if runtime.GOOS == "windows" {
		binary += ".exe"
	}
	return binary
}

// runBinary runs a GoForge binary in dir and fails the test if it fails.
func runBinary(t *testing.T, dir, binary string, args ...string) {
	t.Helper()
	cmd := exec.Command(binary, args...)
	cmd.Dir = dir
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("goforge %s: %v\n%s", strings.Join(args, " "), err, out)
	}
}

// buildAndStart builds the project, starts it with env, and returns its URL.
func buildAndStart(t *testing.T, project string, env ...string) string {
	t.Helper()
	binary := filepath.Join(t.TempDir(), "shop")
	if runtime.GOOS == "windows" {
		binary += ".exe"
	}
	runGo(t, project, "build", "-o", binary, ".")
	baseURL, _ := startServer(t, binary, env...)
	return baseURL
}

// editFile replaces the one occurrence of old in path with new.
func editFile(t *testing.T, path, old, new string) {
	t.Helper()
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if n := strings.Count(string(content), old); n != 1 {
		t.Fatalf("%s contains %q %d times, want once", path, old, n)
	}
	if err := os.WriteFile(path, []byte(strings.Replace(string(content), old, new, 1)), 0o644); err != nil {
		t.Fatal(err)
	}
}

type marker struct {
	name string // e.g. "routes"
	file string // relative to the project
	line string // the whole line, with its newline
}

// findMarkers returns every `// goforge:` marker line in project's Go files.
func findMarkers(t *testing.T, project string) []marker {
	t.Helper()
	var markers []marker
	err := filepath.WalkDir(project, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(path, ".go") {
			return err
		}
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(project, path)
		for _, line := range strings.SplitAfter(string(content), "\n") {
			trimmed := strings.TrimSpace(line)
			if name, ok := strings.CutPrefix(trimmed, "// goforge:"); ok {
				name, _, _ = strings.Cut(name, " ")
				markers = append(markers, marker{name: name, file: filepath.ToSlash(rel), line: line})
			}
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return markers
}

// snapshot returns the content of every file in dir, by path.
func snapshot(t *testing.T, dir string) map[string][]byte {
	t.Helper()
	files := map[string][]byte{}
	err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		content, err := os.ReadFile(path)
		files[path] = content
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	return files
}

// assertUnchanged fails the test if any file in dir was added, removed, or
// changed since before was taken.
func assertUnchanged(t *testing.T, dir string, before map[string][]byte) {
	t.Helper()
	after := snapshot(t, dir)
	for path, content := range after {
		old, ok := before[path]
		switch {
		case !ok:
			t.Errorf("%s was created", path)
		case !bytes.Equal(old, content):
			t.Errorf("%s was changed", path)
		}
	}
	for path := range before {
		if _, ok := after[path]; !ok {
			t.Errorf("%s was removed", path)
		}
	}
}

// copyDir copies the files in src to dst.
func copyDir(t *testing.T, src, dst string) {
	t.Helper()
	err := filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, path)
		target := filepath.Join(dst, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		return os.WriteFile(target, content, 0o644)
	})
	if err != nil {
		t.Fatal(err)
	}
}

// TestRun runs goforge the way main does, with the embedded templates.
func TestRun(t *testing.T) {
	args := os.Args
	t.Cleanup(func() { os.Args = args })

	dir := t.TempDir()
	os.Args = []string{"goforge", "generate", "-n", "shop", "-o", dir, "--yes", "--dry-run"}
	if code := run(); code != 0 {
		t.Errorf("run() generate --dry-run = %d, want 0", code)
	}
	os.Args = []string{"goforge", "no-such-command"}
	if code := run(); code != 1 {
		t.Errorf("run() with an unknown command = %d, want 1", code)
	}
}
